const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  // Great Fox Island is in Virginia, USA (Eastern Shore)
  const greatFoxIsland = ee.Geometry.Polygon([[
    [-75.732, 37.400],
    [-75.728, 37.400],
    [-75.728, 37.404],
    [-75.732, 37.404],
    [-75.732, 37.400]
  ]]);

  const date1999 = ['1999-01-01', '1999-12-31'];
  const date2019 = ['2019-01-01', '2019-12-31'];

  // 2. Data Acquisition - Landsat 5 for 1999, Landsat 8 for 2019
  const landsat5_1999 = ee.ImageCollection('LANDSAT/LT05/C02/T1_L2')
    .filterBounds(greatFoxIsland)
    .filterDate(date1999[0], date1999[1])
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  const landsat8_2019 = ee.ImageCollection('LANDSAT/LC08/C02/T1_L2')
    .filterBounds(greatFoxIsland)
    .filterDate(date2019[0], date2019[1])
    .filter(ee.Filter.lt('CLOUD_COVER', 20));

  // Check if collections have data
  const count1999 = landsat5_1999.size().getInfo();
  const count2019 = landsat8_2019.size().getInfo();

  console.log(`1999 Images: ${count1999}, 2019 Images: ${count2019}`);

  if (count1999 === 0 || count2019 === 0) {
    console.log("<answer>C1</answer>");
    return;
  }

  // Get median composites
  const img1999 = landsat5_1999.median();
  const img2019 = landsat8_2019.median();

  // Function to calculate NDWI and classify land/water
  function calculateLandArea(img, landsatType) {
    let green, nir;

    if (landsatType === 'L5') {
      green = img.select('SR_B2');  // Green band for Landsat 5
      nir = img.select('SR_B4');    // NIR band for Landsat 5
    } else { // Landsat 8
      green = img.select('SR_B3');  // Green band for Landsat 8
      nir = img.select('SR_B5');    // NIR band for Landsat 8
    }

    // Calculate NDWI
    const ndwi = green.subtract(nir).divide(green.add(nir));

    // Classify: land = NDWI < 0, water = NDWI >= 0
    const landMask = ndwi.lt(0);

    // Count land pixels
    const pixelCount = landMask.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: greatFoxIsland,
      scale: 30,
      maxPixels: 1e9
    }).get('constant');

    return pixelCount;
  }

  // Calculate land areas
  const landArea1999 = calculateLandArea(img1999, 'L5').getInfo();
  const landArea2019 = calculateLandArea(img2019, 'L8').getInfo();

  console.log(`1999 Land Pixels: ${landArea1999}`);
  console.log(`2019 Land Pixels: ${landArea2019}`);

  // Check for valid pixels
  if (landArea1999 === 0 || landArea2019 === 0) {
    console.log("<answer>C2</answer>");
    return;
  }

  // Check for calculation failures
  if (landArea1999 === null || landArea2019 === null || 
      isNaN(landArea1999) || isNaN(landArea2019)) {
    console.log("<answer>C3</answer>");
    return;
  }

  // Calculate area in square meters (30m resolution)
  const area1999 = landArea1999 * 30 * 30;
  const area2019 = landArea2019 * 30 * 30;

  console.log(`1999 Area: ${area1999.toFixed(0)} m²`);
  console.log(`2019 Area: ${area2019.toFixed(0)} m²`);
  console.log(`Change: ${((area2019 - area1999) / area1999 * 100).toFixed(1)}%`);

  // Determine answer
  if (area2019 < area1999) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
